/* ---------- #35 · 베드로전서 4:7-11 · 기도하고 뜨겁게 사랑해요 (2026.11.16–11.22) ---------- */
var VERSES35=[[7, "만물의 마지막이 가까이 왔으니 그러므로 너희는 정신을 차리고 근신하여 기도하라", "The end of all things is at hand; therefore be self-controlled and sober-minded for the sake of your prayers.", 1], [8, "무엇보다도 뜨겁게 서로 사랑할지니 사랑은 허다한 죄를 덮느니라", "Above all, keep loving one another earnestly, since love covers a multitude of sins.", 1], [9, "서로 대접하기를 원망 없이 하고", "Show hospitality to one another without grumbling."], [10, "각각 은사를 받은 대로 하나님의 여러 가지 은혜를 맡은 선한 청지기 같이 서로 봉사하라", "As each has received a gift, use it to serve one another, as good stewards of God's varied grace:"], [11, "만일 누가 말하려면 하나님의 말씀을 하는 것 같이 하고 누가 봉사하려면 하나님이 공급하시는 힘으로 하는 것 같이 하라 이는 범사에 예수 그리스도로 말미암아 하나님이 영광을 받으시게 하려 함이니 그에게 영광과 권능이 세세에 무궁하도록 있느니라 아멘", "whoever speaks, as one who speaks oracles of God; whoever serves, as one who serves by the strength that God supplies—in order that in everything God may be glorified through Jesus Christ. To him belong glory and dominion forever and ever. Amen."]];
var BIBLE35={"1pe": {"4": {"7": ["만물의 마지막이 가까이 왔으니 그러므로 너희는 정신을 차리고 근신하여 기도하라", "The end of all things is at hand; therefore be self-controlled and sober-minded for the sake of your prayers."], "8": ["무엇보다도 뜨겁게 서로 사랑할지니 사랑은 허다한 죄를 덮느니라", "Above all, keep loving one another earnestly, since love covers a multitude of sins."], "9": ["서로 대접하기를 원망 없이 하고", "Show hospitality to one another without grumbling."], "10": ["각각 은사를 받은 대로 하나님의 여러 가지 은혜를 맡은 선한 청지기 같이 서로 봉사하라", "As each has received a gift, use it to serve one another, as good stewards of God's varied grace:"], "11": ["만일 누가 말하려면 하나님의 말씀을 하는 것 같이 하고 누가 봉사하려면 하나님이 공급하시는 힘으로 하는 것 같이 하라 이는 범사에 예수 그리스도로 말미암아 하나님이 영광을 받으시게 하려 함이니 그에게 영광과 권능이 세세에 무궁하도록 있느니라 아멘", "whoever speaks, as one who speaks oracles of God; whoever serves, as one who serves by the strength that God supplies—in order that in everything God may be glorified through Jesus Christ. To him belong glory and dominion forever and ever. Amen."]}}};
var LESSONS35={"mon": {"name": "마음 열기", "tag": "OPEN OUR HEARTS", "title": "말씀 속으로 들어가요!", "en": "Feel the Story!", "color": "#F6D6D1", "ink": "#7A3A35", "teaser": "어려운 때에 함께 모여 편지를 듣는 사람들", "qs": [{"type": "multi", "free": true, "label": "모두 고르기 · 벧전 4:7", "q": "예수님을 믿는다는 이유로 어려움을 겪던 사람들이 함께 모여 베드로의 편지를 듣고 있어요. 여러분이 그 자리에 있다면 어떤 소리가 들릴까요? 모두 골라요.", "en": "Imagine you are with Christians facing hard times because they believe in Jesus. As they listen to Peter's letter, what sounds might you hear? Choose all you like.", "opts": [["편지를 읽어 주는 목소리", "Someone reading the letter"], ["조용히 기도하는 소리", "People praying quietly"], ["서로 위로하는 목소리", "People comforting one another"]], "answer": [0, 1, 2], "ok": "좋아요! 그 자리의 소리를 상상해 봤어요."}, {"type": "multi", "free": true, "label": "모두 고르기 · 벧전 4:9", "q": "베드로는 “서로 대접하기를 원망 없이 하고”(9절)라고 말했어요. 여러분이 그 자리에 있다면 사람들이 어떤 모습으로 서로를 도와주고 있을까요? 모두 골라요.", "en": "Peter said, “Show hospitality to one another without grumbling.” (v. 9) How might you see people helping one another? Choose all you like.", "opts": [["배고픈 사람에게 기쁜 마음으로 음식을 나누어 주어요.", "Sharing food gladly with someone who is hungry."], ["혼자 있는 사람을 반갑게 맞아 주어요.", "Welcoming someone who is alone."], ["쉴 곳이 필요한 사람에게 자리를 내어 주어요.", "Offering a place to rest to someone who needs it."]], "answer": [0, 1, 2], "ok": "멋져요! 원망 없는 대접이 어떤 모습인지 떠올려 봤어요."}, {"type": "text", "label": "써 보기 · 벧전 4:8", "q": "만약 여러분이 슬프고 걱정되는 마음으로 그 자리에 앉아 있다면, 누군가 여러분에게 어떤 사랑을 보여 주었으면 좋겠나요?", "en": "If you were sitting there feeling sad or worried, how would you want someone to show you love?", "ph": "내가 받고 싶은 사랑", "ok": "잘했어요! 내가 받고 싶은 사랑을 생각해 봤어요."}, {"type": "pickmany", "label": "그림 고르기 · 벧전 4:8", "q": "베드로의 편지를 듣던 사람들이 어려움 속에서도 서로 사랑하는 모습을 상상해 보세요. 그들의 얼굴에는 어떤 표정이 보일까요? 모두 골라요.", "en": "Imagine the people listening to Peter's letter showing love during hard times. What expressions might you see? Choose all you like.", "opts": [["기쁜 얼굴", "Happy", "f_happy"], ["평안한 얼굴", "Peaceful", "f_peace"], ["감동한 얼굴", "Touched", "f_touch"], ["걱정하는 얼굴", "Worried", "f_worry"]], "ok": "좋아요! 걱정하는 얼굴이어도 괜찮아요. 어려움 속에서도 서로 사랑할 수 있어요."}]}, "tue": {"name": "말씀 찾기", "tag": "VIEWING WHAT HAS BEEN GIVEN", "title": "말씀에 있는 그대로 찾아요", "en": "Explore the Word.", "color": "#E1DBF8", "ink": "#4F4290", "teaser": "마지막이 가까이 왔으니 무엇을 할까요?", "qs": [{"type": "single", "label": "고르기 · 7절", "q": "베드로는 만물의 마지막이 가까이 왔으니 무엇을 하라고 했나요?", "en": "What did Peter tell believers to do because the end of all things was near?", "opts": [["기도해요", "Pray"], ["걱정해요", "Worry"], ["숨어요", "Hide"]], "answer": 0, "ok": "맞아요! 베드로는 정신을 차리고 기도하라고 했어요.", "no": "7절을 다시 읽어 볼까요?"}, {"type": "blanks", "label": "빈칸 채우기 · 8절", "q": "베드로는 무엇보다도 무엇을 하라고 했나요? 알맞은 말을 골라 빈칸에 넣어요.", "en": "What did Peter tell believers to do above all?", "lines": [["“무엇보다도 뜨겁게 서로 ", 0, " 할지니”"]], "words": ["기도", "사랑", "봉사"], "answers": ["사랑"], "ok": "맞아요! 무엇보다도 뜨겁게 서로 사랑하라고 했어요."}, {"type": "single", "label": "고르기 · 9절", "q": "베드로는 우리가 서로 대접할 때 어떻게 하라고 했나요?", "en": "How did Peter say we should show hospitality to one another?", "opts": [["원망 없이", "Without grumbling"], ["불평하면서", "With complaining"], ["자랑하면서", "While showing off"]], "answer": 0, "ok": "맞아요! 원망 없이 서로 대접하라고 했어요.", "no": "9절을 다시 읽어 볼까요?"}, {"type": "match", "label": "짝 맞추기 · 11절", "q": "베드로는 말하는 사람과 봉사하는 사람이 각각 어떻게 하라고 했나요? 왼쪽을 누르고 알맞은 것을 오른쪽에서 눌러요.", "en": "What did Peter tell those who speak and serve to do? Tap the left, then tap the matching answer on the right.", "left": [["말하는 사람", "One who speaks"], ["봉사하는 사람", "One who serves"]], "right": [["하나님께서 주시는 힘으로 섬겨요.", "Serve with God's strength."], ["하나님의 말씀을 전해요.", "Speak God's words."]], "answer": [1, 0], "ok": "모두 맞았어요! 말하는 사람은 하나님의 말씀을 전하고, 봉사하는 사람은 하나님이 주시는 힘으로 섬겨요."}]}, "wed": {"name": "숨은 이야기", "tag": "FINDING HIDDEN STORIES", "title": "왜 그렇게 행동했을까요?", "en": "Why Did They Act That Way?", "color": "#DCE7C6", "ink": "#44572A", "teaser": "기도하고 사랑하고 섬기는 이유", "qs": [{"type": "single", "label": "고르기 · 7절", "q": "베드로는 왜 어려운 때에도 기도하라고 했을까요? 알맞은 말을 골라요.", "en": "Why did Peter tell believers to pray during hard times? Choose the correct answer.", "opts": [["하나님을 의지하기 위해서", "To trust God."], ["하나님을 잊어버리기 위해서", "To forget God."]], "answer": 0, "ok": "맞아요! 기도는 하나님을 의지하는 믿음의 표현이에요.", "no": "다시 생각해 봐요. 어려울 때 누구를 의지할 수 있을까요?"}, {"type": "single", "label": "☆ 고르기 · 8절", "q": "베드로는 “사랑은 허다한 죄를 덮느니라”라고 했어요. 어떤 모습이 이 말씀에 더 가까울까요?", "en": "Peter said, “Love covers a multitude of sins.” Which action shows this love?", "opts": [["친구의 실수를 계속 놀려요.", "Keep teasing a friend for making a mistake."], ["친구의 실수를 용서하고 계속 사랑해요.", "Forgive a friend and keep loving them."]], "answer": 1, "ok": "맞아요! 사랑은 실수를 용서하고 관계를 지켜 가요.", "no": "사랑은 친구의 실수를 어떻게 대할까요? 다시 생각해 봐요."}, {"type": "blanks", "label": "빈칸 채우기 · 9절", "q": "베드로는 왜 원망 없이 서로 대접하라고 했을까요? 알맞은 말을 골라 빈칸에 넣어요.", "en": "Why did Peter tell believers to welcome others without grumbling?", "lines": [["다른 사람을 도울 때 ", 0, "하기보다 ", 1, "하는 마음이 중요해요."]], "words": ["사랑", "불평"], "answers": ["불평", "사랑"], "ok": "맞아요! 불평하기보다 사랑하는 마음이 중요해요."}, {"type": "multi", "label": "모두 찾기 · 10절", "q": "베드로는 하나님께 받은 은사로 서로 봉사하라고 했어요. 말씀에 맞는 행동을 모두 찾아요.", "en": "Peter told believers to use God's gifts to serve one another. Choose all the actions that follow his teaching.", "opts": [["내가 잘하는 것을 친구들에게 자랑해요.", "Show off what I'm good at."], ["어려워하는 친구에게 친절하게 가르쳐 줘요.", "Kindly teach a friend who needs help."], ["내가 가진 것을 필요한 친구와 나누어요.", "Share what I have with a friend in need."]], "answer": [1, 2], "ok": "모두 맞았어요! 받은 것으로 친구를 돕고 나눠요.", "no": "받은 것은 자랑하는 것이 아니라 서로 섬기는 데 써요. 다시 골라 봐요."}]}, "thu": {"name": "하나님 마음", "tag": "ENCOUNTERING THE HEART OF GOD", "title": "하나님의 마음을 알아가요!", "en": "Getting to Know God's Heart!", "color": "#FBE3D2", "ink": "#8A4A22", "teaser": "하나님은 어떤 분이실까요?", "qs": [{"type": "single", "label": "고르기 · 10절", "q": "베드로는 우리가 받은 은사를 ‘하나님의 여러 가지 은혜’와 연결해서 말했어요. 이 말씀을 통해 하나님은 어떤 분이심을 알 수 있나요?", "en": "Peter connects our gifts with God's many kinds of grace. What does this tell us about God?", "opts": [["하나님은 우리 각 사람에게 다양한 은혜를 주시는 분이에요.", "God gives different kinds of grace to each of us."], ["하나님은 모든 사람에게 똑같은 재능만 주시는 분이에요.", "God gives everyone exactly the same talents."]], "answer": 0, "ok": "맞아요! 하나님은 각 사람에게 다양한 은혜를 주세요.", "no": "10절을 다시 읽어 볼까요?"}, {"type": "single", "label": "고르기 · 11절", "q": "11절을 읽어 보세요. 우리가 다른 사람을 섬길 때 하나님께서는 무엇을 주시나요?", "en": "Read verse 11. What does God provide when we serve others?", "opts": [["힘", "Strength"], ["걱정", "Worry"], ["두려움", "Fear"]], "answer": 0, "ok": "맞아요! 하나님은 섬길 힘을 공급해 주세요.", "no": "11절을 다시 읽어 볼까요?"}, {"type": "single", "label": "고르기 · 10절", "q": "베드로는 우리가 하나님의 은혜를 맡은 ‘선한 청지기’라고 했어요. 하나님께서 우리에게 은혜를 맡기신 것을 통해 하나님의 어떤 마음을 알 수 있을까요?", "en": "Peter called us stewards of God's grace. What does this show us about God's heart?", "opts": [["하나님은 우리에게 은혜를 맡기시고 서로 섬기는 일에 참여하게 하세요.", "God trusts us with His grace and invites us to serve others."], ["하나님은 우리가 받은 은혜를 다른 사람과 나누지 않기를 바라세요.", "God wants us to keep His grace to ourselves."]], "answer": 0, "ok": "맞아요! 하나님은 우리가 은혜를 나누는 일에 함께하게 하세요.", "no": "청지기는 맡은 것을 어떻게 사용하는 사람일까요?"}, {"type": "blanks", "label": "빈칸 채우기 · 11절", "q": "베드로는 우리가 서로 섬길 때 하나님께 영광이 돌아가게 하라고 했어요. 우리의 섬김을 통해 누구의 사랑과 은혜가 드러나야 할까요?", "en": "Peter said our service should bring glory to God. Whose love and grace should shine through our service?", "lines": [["하나님은 우리의 섬김을 통해 ", 0, " 사랑과 은혜가 드러나기를 원하세요."]], "words": ["나의", "하나님의"], "answers": ["하나님의"], "ok": "맞아요! 우리의 섬김을 통해 하나님의 사랑과 은혜가 드러나요."}]}, "fri": {"name": "내 삶으로", "tag": "INTO MY LIFE", "title": "나는 어떻게 살아야 할까요?", "en": "How Should I Live?", "color": "#FBEBB8", "ink": "#6E5410", "teaser": "하나님의 사랑을 기억하며 살아요", "qs": [{"type": "pick", "label": "하나 고르기", "q": "이번 주에 베드로가 가르쳐 준 말씀 가운데 나에게 가장 필요한 것은 무엇인가요? 하나를 골라요.", "en": "Which of Peter's teachings do you need most in your life? Choose one.", "opts": [["어려울 때 하나님께 기도해요.", "Pray to God during hard times."], ["친구의 실수를 용서하고 사랑해요.", "Forgive and love a friend."], ["불평하지 않고 다른 사람을 도와요.", "Help others without complaining."], ["하나님께 받은 것으로 서로 섬겨요.", "Use God's gifts to serve others."]], "ok": "좋아요! 나에게 필요한 말씀을 골랐어요."}, {"type": "fill", "label": "써 보기", "q": "내가 사랑하기 어렵거나 도와주기 힘들었던 때가 있었나요? 그때 나는 어떻게 행동했나요?", "en": "Was there a time when it was hard to love or help someone? What did you do?", "parts": ["그때 나는 ", 0], "ok": "솔직하게 돌아봤어요. 하나님께 도움을 구해요!"}, {"type": "multi", "free": true, "label": "모두 고르기", "q": "이번 주에 하나님의 사랑을 기억하며 실천하고 싶은 것을 모두 골라요.", "en": "Choose all the ways you want to show God's love this week.", "opts": [["걱정될 때 하나님께 기도할래요.", "Pray when I'm worried."], ["친구의 실수를 용서할래요.", "Forgive a friend's mistake."], ["불평하지 않고 도울래요.", "Help without complaining."], ["내가 가진 것을 나눌래요.", "Share what I have."]], "answer": [0, 1, 2, 3], "ok": "멋져요! 하나님이 먼저 사랑해 주셨으니 우리도 사랑할 수 있어요."}], "confess": {"title": "이번 주 믿음의 고백", "en": "My Faith Confession", "ko": ["하나님, 저를 먼저 사랑해 주셔서 감사해요.", "하나님께서 보여 주신 그 사랑으로 저도 다른 사람들을 사랑할 수 있도록 도와주세요.", "그리고 기쁜 마음으로 다른 사람들을 섬길 수 있도록 힘을 주세요."], "enLines": ["Thank You, God, for loving me first.", "Help me love others with the love You have shown me.", "Give me strength to serve others with a joyful heart."]}}};
var LESSONS35_EN={"mon": {"name": "Open Hearts", "title": "Feel the Story!", "teaser": "People gathering to hear a letter in hard times", "qs": [{"label": "Choose all · 1 Pet 4:7", "ok": "Good! You imagined the sounds in that room.", "q": "Imagine you are with Christians facing hard times because they believe in Jesus. As they listen to Peter's letter, what sounds might you hear? Choose all you like."}, {"label": "Choose all · 1 Pet 4:9", "ok": "Wonderful! You pictured what hospitality without grumbling looks like.", "q": "Peter said, “Show hospitality to one another without grumbling.” (v. 9) How might you see people helping one another? Choose all you like."}, {"label": "Write · 1 Pet 4:8", "ok": "Well done! You thought about the love you would want to receive.", "ph": "The love I want to receive", "q": "If you were sitting there feeling sad or worried, how would you want someone to show you love?"}, {"label": "Choose pictures · 1 Pet 4:8", "ok": "Good! A worried face is okay too. We can love one another even in hard times.", "q": "Imagine the people listening to Peter's letter showing love during hard times. What expressions might you see? Choose all you like."}]}, "tue": {"name": "Find the Word", "title": "Explore the Word.", "teaser": "What should we do since the end is near?", "qs": [{"label": "Choose · v. 7", "ok": "That’s right! Peter told them to be self-controlled and pray.", "no": "Let’s read verse 7 again.", "q": "What did Peter tell believers to do because the end of all things was near?"}, {"label": "Fill in the blank · v. 8", "ok": "That’s right! Above all, love one another deeply.", "lines": [["“Above all, ", 0, " one another deeply.”"]], "wordsEn": ["Pray", "Love", "Serve"], "q": "What did Peter tell believers to do above all?"}, {"label": "Choose · v. 9", "ok": "That’s right! Show hospitality without grumbling.", "no": "Let’s read verse 9 again.", "q": "How did Peter say we should show hospitality to one another?"}, {"label": "Match · v. 11", "ok": "All correct! Those who speak share God’s words, and those who serve do so with the strength God supplies.", "q": "What did Peter tell those who speak and serve to do? Tap the left, then tap the matching answer on the right."}]}, "wed": {"name": "Hidden Story", "title": "Why Did They Act That Way?", "teaser": "Why pray, love, and serve?", "qs": [{"label": "Choose · v. 7", "ok": "That’s right! Prayer shows that we trust God.", "no": "Let’s think again. Who can we trust in hard times?", "q": "Why did Peter tell believers to pray during hard times? Choose the correct answer."}, {"label": "Choose ☆ · v. 8", "ok": "That’s right! Love forgives mistakes and keeps the friendship.", "no": "How does love treat a friend’s mistake? Let’s think again.", "q": "Peter said, “Love covers a multitude of sins.” Which action shows this love?"}, {"label": "Fill in the blanks · v. 9", "ok": "That’s right! Love matters more than complaining.", "lines": [["When helping others, show ", 1, " instead of ", 0, "."]], "wordsEn": ["love", "complaining"], "q": "Why did Peter tell believers to welcome others without grumbling?"}, {"label": "Choose all · v. 10", "ok": "All correct! We use what we have received to help and share.", "no": "What we receive is for serving one another, not for showing off. Let’s choose again.", "q": "Peter told believers to use God's gifts to serve one another. Choose all the actions that follow his teaching."}]}, "thu": {"name": "God's Heart", "title": "Getting to Know God's Heart!", "teaser": "What is God like?", "qs": [{"label": "Choose · v. 10", "ok": "That’s right! God gives different kinds of grace to each of us.", "no": "Let’s read verse 10 again.", "q": "Peter connects our gifts with God's many kinds of grace. What does this tell us about God?"}, {"label": "Choose · v. 11", "ok": "That’s right! God supplies the strength to serve.", "no": "Let’s read verse 11 again.", "q": "Read verse 11. What does God provide when we serve others?"}, {"label": "Choose · v. 10", "ok": "That’s right! God invites us to share His grace.", "no": "What does a steward do with what is entrusted to him?", "q": "Peter called us stewards of God's grace. What does this show us about God's heart?"}, {"label": "Fill in the blank · v. 11", "ok": "That’s right! God’s love and grace shine through our service.", "lines": [["God wants ", 0, " love and grace to shine through our service."]], "wordsEn": ["my", "God's"], "q": "Peter said our service should bring glory to God. Whose love and grace should shine through our service?"}]}, "fri": {"name": "Into My Life", "title": "How Should I Live?", "teaser": "Living in the remembrance of God’s love", "qs": [{"label": "Choose one", "ok": "Good! You chose the teaching you need most.", "q": "Which of Peter's teachings do you need most in your life? Choose one."}, {"label": "Write", "ok": "Thank you for being honest. Let’s ask God for help!", "parts": ["I ", 0], "q": "Was there a time when it was hard to love or help someone? What did you do?"}, {"label": "Choose all", "ok": "Wonderful! God loved us first, so we can love others too.", "q": "Choose all the ways you want to show God's love this week."}]}};
/* parent guide #35 (Korean text from the church's guide; the English is our translation) */
var PG35={"week": {"chip": "이번 주 말씀 한눈에 보기", "title": "기도하고 뜨겁게 사랑해요", "sub": "베드로전서 — 어려움 속에서도 사랑하는 그리스도인", "period": "2026.11.16–11.22 · 부모님을 위한 묵상 가이드", "ref": "베드로전서 4:7-11", "color": "#F6D6D1", "ink": "#7A3A35", "desc": "한 주의 핵심 메시지와 주제", "refs": [["본문", "베드로전서 4:7–11"], ["암송 말씀", "베드로전서 4:7–8"]], "parts": [["이번 주 묵상의 이해", ["베드로전서는 예수 그리스도를 믿는다는 이유로 여러 어려움과 고난을 겪던 그리스도인들에게 보내진 편지입니다. 당시 성도들은 자신들이 살아가는 사회에서 오해와 비난, 배척을 경험하기도 했습니다. 베드로는 이러한 상황에 놓인 성도들에게 고난을 피할 방법을 알려 주기보다, 어려움 속에서도 그리스도인으로서 어떻게 살아가야 하는지를 가르쳐 줍니다.", "특별히 베드로전서 4장 7절은 \"만물의 마지막이 가까이 왔으니\"라는 선언으로 시작합니다. 이것은 단순히 세상의 끝을 두려워하라는 경고가 아닙니다. 예수 그리스도의 죽음과 부활로 하나님의 구원이 이미 시작되었으며, 그 완성을 기다리는 성도들이 지금 어떻게 살아야 하는지를 생각하게 하는 말씀입니다.", "베드로는 이러한 시대를 살아가는 그리스도인들에게 세 가지 중요한 삶의 태도를 권면합니다.", "첫째, <b>정신을 차리고 근신하여 기도하는 것</b>입니다. 고난과 어려움이 찾아올 때 우리는 두려움과 걱정에 사로잡히기 쉽습니다. 그러나 베드로는 상황에 압도되기보다 하나님을 바라보며 기도하라고 권면합니다. 기도는 단순히 어려움을 해결하기 위한 수단이 아니라, 어떤 상황에서도 하나님을 의지하며 믿음을 지켜 가는 삶의 태도입니다.", "둘째, <b>무엇보다 뜨겁게 서로 사랑하는 것</b>입니다. 베드로는 \"사랑은 허다한 죄를 덮느니라\"(8절)라고 말합니다. 공동체 안에서도 사람들은 서로 실수하고 상처를 주며 갈등을 경험합니다. 그럼에도 서로의 허물을 붙잡고 비난하기보다 용서와 사랑으로 관계를 지켜 가라는 것입니다. 이어서 원망 없이 서로 대접하라는 말씀은 사랑이 단순한 감정에 머무르지 않고 다른 사람을 기꺼이 받아들이고 돌보는 행동으로 나타나야 한다는 것을 보여 줍니다.", "셋째, <b>하나님께 받은 은사로 서로 봉사하는 것</b>입니다. 베드로는 성도들을 하나님의 여러 가지 은혜를 맡은 '선한 청지기'라고 부릅니다. 우리가 가진 능력과 재능, 다른 사람을 섬길 기회는 나 자신을 드러내기 위한 것이 아니라 하나님의 은혜를 나누기 위해 맡겨진 것입니다. 하나님께서는 우리가 받은 것을 다른 사람을 위해 사용할 수 있도록 힘도 공급하십니다.", "그리고 베드로는 이 모든 권면을 하나의 목적으로 연결합니다. \"이는 범사에 예수 그리스도로 말미암아 하나님이 영광을 받으시게 하려 함이니\"(11절). 우리가 기도하고 사랑하며 서로 섬기는 궁극적인 목적은 자신의 선함을 드러내는 것이 아니라 하나님께 영광을 돌리는 것입니다.", "아이들에게는 이 부분이 조금 추상적으로 느껴질 수 있습니다. 아이가 다른 사람을 친절하게 돕는 모습을 볼 때 부모가 기뻐하는 것처럼, 하나님께서도 우리가 서로 사랑하며 살아가는 것을 기뻐하신다고 설명해 줄 수 있습니다. 그러나 여기에서 한 걸음 더 나아가야 합니다.", "<b>우리가 착한 일을 하기 때문에 하나님께 사랑받는 것이 아니라, 하나님께서 먼저 우리를 사랑하셨기 때문에 우리도 다른 사람을 사랑하는 것입니다.</b> 그리고 하나님께 받은 사랑과 힘으로 다른 사람을 섬길 때, 우리의 행동은 하나님의 은혜를 드러내는 통로가 될 수 있습니다.", "이번 주에는 아이들이 선한 행동을 얼마나 많이 실천했는지를 평가하기보다, 하나님께 받은 사랑을 기억하고 그 은혜를 의지하며 다른 사람을 사랑하는 마음을 배워 가도록 도와주세요."]]], "verse": ["베드로전서 4:7–8", "만물의 마지막이 가까이 왔으니 그러므로 너희는 정신을 차리고 근신하여 기도하라 무엇보다도 뜨겁게 서로 사랑할지니 사랑은 허다한 죄를 덮느니라"], "closing": {"title": "부모님께 드리는 마지막 안내", "body": ["이번 주 말씀은 고난과 어려움 속에서도 그리스도인들이 어떤 삶을 살아야 하는지를 가르쳐 줍니다.", "베드로는 어려움을 겪는 성도들에게 자신만을 보호하며 살아가라고 말하지 않습니다. 오히려 정신을 차리고 기도하며, 무엇보다 서로 뜨겁게 사랑하고, 원망 없이 대접하며, 하나님께 받은 은사로 서로 섬기라고 권면합니다.", "그러나 이러한 삶은 우리의 의지와 노력만으로 이루어지는 것이 아닙니다. 하나님께서 먼저 은혜를 베푸시고, 사랑할 힘과 섬길 힘을 공급하시기 때문입니다.", "이번 주에는 부모님도 자녀와 함께 자신의 삶을 돌아보면 좋겠습니다. 우리 역시 바쁘고 지칠 때 다른 사람을 사랑하기 어려울 수 있습니다. 그럴 때 하나님의 은혜를 기억하고 도움을 구하며, 작은 사랑과 섬김을 실천하는 모습을 자녀에게 보여 주세요."], "keyTitle": "이번 주 핵심", "key": "우리를 먼저 사랑하신 하나님의 은혜가 기도와 사랑, 섬김을 통해 우리의 가정과 공동체 가운데 드러나기를 소망합니다."}}, "mon": {"day": "월요일", "name": "마음 열기", "sub": "말씀 속으로 들어가요!", "title": "베드로전서 4:7–9", "color": "#F6D6D1", "ink": "#7A3A35", "focus": "월요일은 베드로의 편지를 듣던 그리스도인들의 상황을 상상하며 말씀 속으로 들어가는 날입니다.", "body": ["아이들은 예수님을 믿는다는 이유로 어려움을 겪던 사람들이 함께 모여 편지를 듣는 장면을 떠올립니다. 편지를 읽어 주는 목소리, 조용히 기도하는 소리, 서로 위로하는 목소리를 상상하면서 그곳에 있던 사람들의 마음을 느껴 보도록 합니다.", "특히 2번 질문에서는 베드로가 권면한 '원망 없는 대접'이 실제로 어떤 모습이었을지 생각합니다. 음식을 나누거나, 혼자 있는 사람을 반갑게 맞아 주거나, 쉴 곳이 필요한 사람에게 자리를 내어 주는 모습을 통해 사랑이 구체적인 행동으로 나타난다는 사실을 느낄 수 있습니다.", "여기에서 부모님이 기억해야 할 것은 <b>당시 그리스도인들도 자신의 삶이 힘들고 어려웠다는 사실</b>입니다. 다른 사람을 돕기에 충분히 여유로운 상황이 아니었을 수도 있습니다. 그럼에도 베드로는 서로 사랑하고 돌보라고 권면했습니다.", "3번에서는 자신이 슬프거나 걱정스러울 때 어떤 사랑을 받고 싶은지 생각합니다. 아이가 자신의 경험을 자연스럽게 이야기하도록 도와주세요. 누군가 곁에 있어 주거나, 이야기를 들어 주거나, 따뜻하게 안아 주었던 경험도 좋은 대화의 출발점이 될 수 있습니다.", "마지막 4번에서는 서로 사랑하는 사람들의 표정을 상상합니다. 기쁜 얼굴과 평안한 얼굴뿐 아니라 걱정하는 얼굴을 선택해도 괜찮습니다. 서로 사랑한다고 해서 어려움이 모두 사라지는 것은 아니기 때문입니다. 오히려 걱정과 두려움 속에서도 서로를 위로하고 돌볼 수 있다는 사실에 주목해 주세요.", "<b>월요일에는 정답을 찾기보다, 어려움 속에서 서로 사랑하는 사람들의 마음을 충분히 느끼는 것이 중요합니다.</b>", "부모님께: 본문은 베드로의 권면을 기록한 것이지 편지를 받은 사람들의 구체적인 반응을 기록한 것은 아닙니다. 아이들이 상상한 장면을 역사적 사실로 단정하지 않도록 안내해 주세요."]}, "tue": {"day": "화요일", "name": "말씀 찾기", "sub": "말씀에 있는 그대로 찾아요!", "title": "베드로전서 4:7–11", "color": "#E1DBF8", "ink": "#4F4290", "focus": "화요일은 본문을 자세히 읽으며 베드로가 그리스도인들에게 무엇을 권면했는지 직접 찾아보는 날입니다.", "body": ["1번에서는 '만물의 마지막이 가까이 왔다'는 말씀에 이어 베드로가 기도하라고 권면한 사실을 발견합니다. 여기서 '마지막'이라는 표현을 두려운 사건으로만 설명하지 않도록 주의해 주세요. 베드로는 마지막 때를 살아가는 성도들이 두려움에 빠지기보다 정신을 차리고 하나님께 기도해야 한다고 가르칩니다.", "2번에서는 \"무엇보다도\"라는 표현에 주목해 주세요. 베드로는 여러 가지 권면 가운데 특별히 서로 뜨겁게 사랑하는 일을 강조합니다. '뜨겁게 사랑한다'는 것은 단순히 좋은 감정을 느끼는 것이 아니라 어려움 속에서도 사랑을 지속하려는 진실하고 간절한 태도를 의미합니다.", "3번에서는 '원망 없이'라는 표현을 살펴봅니다. 다른 사람을 도와주는 행동뿐 아니라 그 행동에 담긴 마음도 중요하다는 사실을 발견하도록 도와주세요.", "4번에서는 말하는 사람과 봉사하는 사람이 각각 어떻게 해야 하는지 11절에서 찾아 연결합니다. 말하는 사람은 하나님의 말씀을 전하는 태도로 말하고, 봉사하는 사람은 하나님께서 공급하시는 힘을 의지하여 섬겨야 합니다.", "두 가지 역할은 다르지만 공통점이 있습니다. <b>우리가 하는 말과 행동이 모두 하나님께로부터 받은 은혜와 힘을 의지해야 한다는 것</b>입니다.", "화요일에는 각 질문의 답을 부모님이 먼저 설명하기보다, 아이가 해당 구절을 다시 읽고 정답이 기록된 부분을 직접 찾아보도록 도와주세요."]}, "wed": {"day": "수요일", "name": "숨은 이야기", "sub": "왜 그렇게 행동했을까요?", "title": "베드로전서 4:7–10", "color": "#DCE7C6", "ink": "#44572A", "focus": "수요일에는 베드로가 왜 기도와 사랑, 대접과 섬김을 권면했는지 그 이유를 생각합니다.", "body": ["1번에서는 기도하는 이유를 생각합니다. 기도는 모든 문제를 자신의 힘으로 해결하려는 행동이 아니라 하나님을 의지하는 믿음의 표현입니다. 아이가 어려운 일을 겪을 때 하나님께 자신의 마음을 말씀드릴 수 있다는 사실을 알려 주세요.", "2번은 이번 주 묵상에서 특별히 중요한 질문입니다. \"사랑은 허다한 죄를 덮느니라\"라는 말씀은 다른 사람의 잘못을 무조건 숨기거나 모른 척하라는 의미가 아닙니다. 사랑은 상대방의 허물을 계속 들추어 비난하기보다 용서하며 관계를 회복하려는 태도로 나타납니다.", "친구가 실수했을 때 계속 놀리는 모습과 용서하고 사랑하는 모습을 비교하면서, 베드로가 권면한 사랑이 무엇인지 생각하도록 도와주세요.", "다만 다른 사람의 폭력이나 괴롭힘, 위험한 행동까지 무조건 참아야 한다는 뜻은 아니라는 점을 분명히 알려 주어야 합니다. 잘못된 행동을 바로잡고 어른에게 도움을 요청하는 것은 사랑과 모순되지 않습니다.", "3번에서는 원망 없이 대접해야 하는 이유를 생각합니다. 사람을 돕는 일은 때로 수고와 불편함을 동반합니다. 베드로는 그러한 상황에서도 불평과 원망에 사로잡히기보다 사랑하는 마음으로 서로를 돌보라고 권면합니다.", "여기서 원망 없이 돕는다는 것이 언제나 즐거운 감정을 느껴야 한다는 뜻은 아닙니다. 힘들고 피곤할 수 있지만 다른 사람을 귀찮은 존재로 여기거나 탓하지 않는 태도에 더 가깝습니다.", "4번에서는 하나님께 받은 은사를 사용하는 목적을 생각합니다. 자신이 잘하는 것을 자랑하는 행동과 다른 사람을 돕고 나누는 행동을 비교하면서, 하나님께 받은 것은 자신만을 위한 것이 아니라는 사실을 발견하도록 합니다.", "<b>수요일의 핵심은 베드로의 권면을 단순한 행동 규칙으로 이해하지 않고, 그 행동에 담긴 사랑과 믿음의 태도를 발견하는 것입니다.</b>"]}, "thu": {"day": "목요일", "name": "하나님 마음", "sub": "하나님의 마음을 알아가요!", "title": "베드로전서 4:10–11", "color": "#FBE3D2", "ink": "#8A4A22", "focus": "목요일은 우리가 무엇을 해야 하는지보다, <b>말씀을 통해 하나님이 어떤 분이시며 우리에게 무엇을 주시는지</b> 발견하는 날입니다.", "body": ["1번에서는 '하나님의 여러 가지 은혜'라는 표현에 주목합니다. 하나님께서는 다양한 방법으로 은혜를 베푸시는 분입니다. 우리가 가진 은사는 하나님의 은혜와 연결되어 있으며, 하나님께서 각 사람에게 맡기신 것은 모두 같지 않습니다.", "아이들이 자신이 잘하는 것과 다른 친구가 잘하는 것을 비교하며 우열을 가리지 않도록 도와주세요. 중요한 것은 누가 더 뛰어난가가 아니라 하나님께서 주신 것을 어떻게 받아들이고 사용하는가입니다.", "2번에서는 하나님께서 섬기는 사람에게 힘을 공급하신다는 사실을 발견합니다. 하나님께서는 우리에게 서로 섬기라고 명령만 하시는 분이 아닙니다. 그 말씀에 따라 살아갈 수 있도록 필요한 힘도 공급하시는 분입니다.", "이것은 아이들에게 중요한 위로가 될 수 있습니다. 우리는 언제나 다른 사람을 친절하게 대하거나 사랑할 만큼 충분한 마음을 가지고 있지는 않습니다. 그럴 때 하나님께 도움을 구할 수 있습니다.", "3번에서는 '선한 청지기'라는 표현을 살펴봅니다. 청지기는 주인이 맡긴 것을 책임 있게 관리하는 사람입니다. 베드로는 우리가 하나님의 은혜를 맡은 사람이라고 말합니다. 하나님께서는 우리가 받은 은혜를 혼자 간직하기보다 다른 사람을 섬기는 데 사용하도록 맡기셨습니다. 이것은 우리가 하나님의 은혜를 나누는 일에 참여하도록 부르심을 받았다는 의미입니다.", "4번에서는 하나님의 영광을 생각합니다. 베드로는 우리가 서로 섬기는 모든 일을 통해 예수 그리스도로 말미암아 하나님께 영광이 돌아가게 하라고 권면합니다. 아이들에게는 부모님이 자녀의 사랑과 배려를 보고 기뻐하는 모습을 예로 들 수 있습니다. 그러나 하나님께 영광을 돌리는 것은 단순히 하나님께 칭찬받을 행동을 하는 것보다 더 깊은 의미를 지닙니다. 우리가 받은 사랑과 힘이 하나님께로부터 왔음을 인정하고, 우리의 섬김을 통해 하나님의 사랑과 은혜가 나타나도록 하는 것입니다.", "<b>목요일에는 하나님이 우리에게 은혜를 주시고, 그 은혜를 맡기시며, 서로 섬길 힘까지 공급하시는 분이라는 사실을 발견하도록 안내해 주세요.</b>"]}, "fri": {"day": "금요일", "name": "내 삶으로", "sub": "나는 어떻게 살아야 할까요?", "title": "베드로전서 4:7–11", "color": "#D6ECF5", "ink": "#2F5A72", "focus": "금요일은 한 주 동안 묵상한 말씀을 자신의 삶에 연결하는 날입니다.", "body": ["1번에서는 기도, 용서, 원망 없는 섬김, 은사를 통한 봉사 가운데 지금 자신에게 가장 필요한 말씀을 선택합니다. 아이가 어떤 답을 선택하든 그 이유를 편안하게 이야기하도록 도와주세요.", "2번에서는 누군가를 사랑하거나 도와주기 어려웠던 경험을 돌아봅니다. 이 질문은 아이의 잘못을 찾아내거나 반성문을 쓰게 하기 위한 것이 아닙니다. 자신의 마음과 행동을 정직하게 살펴보는 것이 목적입니다. 아이가 불평했거나 도와주지 못했던 경험을 이야기하더라도 곧바로 꾸짖기보다 왜 그렇게 행동했는지 들어 주세요. 자신의 부족함을 발견하는 일이 하나님의 도움을 구하는 기도로 이어지도록 안내하는 것이 중요합니다.", "3번에서는 이번 주에 하나님의 사랑을 기억하며 실천하고 싶은 행동을 선택합니다. 여러 가지를 모두 실천해야 한다는 부담을 주기보다 한 가지라도 진심으로 실천해 보도록 격려해 주세요.", "마지막 믿음의 고백은 이번 주 묵상의 신학적 중심을 잘 담고 있습니다. \"하나님, 저를 먼저 사랑해 주셔서 감사해요.\" 아이들의 믿음은 자신이 얼마나 착한 일을 했는지에서 출발하지 않습니다. 우리를 먼저 사랑하신 하나님의 은혜에서 시작합니다. 그리고 그 사랑을 받은 아이들이 다른 사람을 사랑하고 섬길 수 있도록 하나님의 도움을 구하는 것으로 묵상을 마무리합니다.", "<b>금요일에는 아이들이 자신의 결심만을 의지하는 것이 아니라, 하나님의 사랑을 기억하고 그분께 섬길 힘을 구하도록 이끌어 주세요.</b>"]}};
var PG35_EN={"week": {"chip": "This Week at a Glance", "title": "Pray and Love Deeply", "sub": "1 Peter — Loving One Another Through Hard Times", "period": "Nov 16 – Nov 22, 2026 · Devotional Guide for Parents", "ref": "1 Peter 4:7–11", "desc": "This week’s main message and theme", "refs": [["Passage", "1 Peter 4:7–11"], ["Memory verse", "1 Peter 4:7–8"]], "parts": [["Understanding This Week's Bible Passage", ["The First Letter of Peter was written to Christians who were experiencing various hardships and suffering because of their faith in Jesus Christ. Many believers faced misunderstanding, criticism, and rejection from the society around them. Rather than simply telling them how to escape their difficulties, Peter taught them how to live faithfully as followers of Christ in the midst of suffering.", "In 1 Peter 4:7, Peter begins with the declaration, \"The end of all things is at hand.\" This is not simply a warning intended to make believers afraid of the end of the world. Through the death and resurrection of Jesus Christ, God's work of salvation has already begun, and believers now live in anticipation of its completion. Peter's words invite Christians to consider how they should live while waiting for Christ's return.", "Peter emphasizes three important attitudes for believers.", "First, <b>be self-controlled, sober-minded, and devoted to prayer.</b> When we face suffering or difficulties, it is easy to become overwhelmed by fear and worry. Yet Peter encourages believers to remain spiritually alert and turn to God in prayer. Prayer is not merely a way to ask God to solve our problems. It is an expression of faith through which we continue to trust and depend on Him in every circumstance.", "Second, <b>above all, love one another deeply.</b> Peter writes, \"Love covers a multitude of sins\" (v. 8). Even within a Christian community, people make mistakes, hurt one another, and experience conflict. Peter calls believers not to continually expose or hold on to one another's faults, but to practice forgiveness and preserve their relationships through love. His instruction to show hospitality without grumbling reminds us that genuine love is more than a feeling. It becomes visible through our willingness to welcome, care for, and serve others.", "Third, <b>use the gifts we have received from God to serve one another.</b> Peter describes believers as good stewards of God's varied grace. Our abilities, talents, and opportunities to serve are not given merely for personal recognition. They are entrusted to us so that God's grace may be shared with others. God also supplies the strength we need to serve faithfully.", "Peter connects all these instructions to one ultimate purpose:", "\"So that in everything God may be glorified through Jesus Christ\" (v. 11).", "The ultimate purpose of prayer, love, and service is not to display our own goodness but to bring glory to God.", "This idea may seem abstract to young children. Parents can explain that just as they feel joy when they see their children showing kindness and helping others, God is pleased when we love and care for one another. However, it is important to go one step further.", "<b>God does not love us because we do good things. Rather, we are able to love others because God has already loved us first.</b> When we serve others with the love and strength He has given us, our actions can become a reflection of His grace.", "This week, instead of focusing on how many good deeds your child completes, help your child remember God's love and learn to depend on His grace while loving others."]]], "verse": ["1 Peter 4:7–8", "The end of all things is at hand; therefore be self-controlled and sober-minded for the sake of your prayers. Above all, keep loving one another earnestly, since love covers a multitude of sins."], "closing": {"title": "A Final Encouragement for Parents", "body": ["This week's passage teaches us how Christians are called to live even in the midst of suffering and difficulties.", "Peter does not tell believers to focus only on protecting themselves. Instead, he encourages them to remain alert in prayer, love one another deeply, show hospitality without grumbling, and use God's gifts to serve one another.", "Yet this kind of life is not accomplished through human effort and determination alone. God is the One who first gives grace and supplies the strength we need to love and serve.", "As you guide your child this week, consider reflecting on these truths together. Parents also experience moments when they are tired, overwhelmed, or find it difficult to love others. In those moments, we too can remember God's grace, ask Him for help, and practice small acts of love and service."], "keyTitle": "Key message", "key": "May the grace of God, who loved us first, be revealed through prayer, love, and service in our families and communities."}, "color": "#F6D6D1", "ink": "#7A3A35"}, "mon": {"day": "Monday", "name": "Open Hearts", "sub": "Feel the Story!", "title": "1 Peter 4:7–9", "focus": "Monday invites children to enter the Bible story by imagining the circumstances of the Christians who received Peter's letter.", "body": ["Children are encouraged to imagine believers gathered together, listening to a letter from Peter while facing hardships because of their faith in Jesus. They may imagine the sound of someone reading the letter, people praying quietly, or believers comforting one another.", "Through these details, help your child consider what the people might have been feeling.", "Question 2 focuses on Peter's instruction to show hospitality without grumbling. Children imagine people sharing food, welcoming someone who is alone, or offering a place to rest to someone in need. These examples help them recognize how love can be expressed through practical actions.", "An important point for parents to remember is that <b>the early Christians were also facing difficulties of their own.</b> They may not always have had enough time, energy, or resources to care for others. Nevertheless, Peter encouraged them to continue loving and caring for one another.", "Question 3 asks children to consider how they would want someone to show them love if they felt sad or worried. Encourage your child to share personal experiences naturally. Perhaps someone stayed beside them, listened to their worries, or comforted them with a hug. These memories can help children understand the comfort that love brings.", "In Question 4, children imagine the facial expressions of people showing love to one another. It is perfectly acceptable for them to choose worried expressions as well as happy or peaceful ones. Loving one another does not mean that every problem or worry disappears. Rather, believers can continue to comfort and care for one another even while experiencing fear or difficulty.", "<b>The goal of Monday is not to find the correct answer, but to help children experience the emotions of people who were learning to love one another during difficult times.</b>", "Note for Parents: The passage records Peter's instructions, but it does not describe the exact reactions of those who received his letter. Help children understand that these scenes are imaginative reflections based on the passage, not recorded historical events."], "color": "#F6D6D1", "ink": "#7A3A35"}, "tue": {"day": "Tuesday", "name": "Find the Word", "sub": "Explore the Word!", "title": "1 Peter 4:7–11", "focus": "Tuesday focuses on carefully reading the passage and discovering what Peter actually instructed believers to do.", "body": ["Question 1 helps children identify Peter's command to pray because the end of all things is near. Be careful not to explain \"the end\" only as a frightening future event. Peter teaches believers to remain spiritually alert and pray rather than become overwhelmed by fear.", "In Question 2, draw attention to the phrase \"above all.\" Among his many instructions, Peter places special emphasis on loving one another deeply. Loving deeply is not simply having warm feelings toward someone. It includes a sincere and lasting commitment to love, even when circumstances are difficult.", "Question 3 highlights the words \"without grumbling.\" Help children recognize that both our actions and the attitudes behind them matter when we care for others.", "Question 4 asks children to match Peter's instructions for those who speak and those who serve. Those who speak should do so as people communicating God's words, while those who serve should depend on the strength God supplies.", "Although these responsibilities are different, they share an important truth: <b>both our words and actions should depend on the grace and strength God provides.</b>", "Rather than explaining each answer immediately, encourage your child to return to the corresponding verse and find the answer directly in Scripture."], "color": "#E1DBF8", "ink": "#4F4290"}, "wed": {"day": "Wednesday", "name": "Hidden Story", "sub": "Look for Why!", "title": "1 Peter 4:7–10", "focus": "Wednesday encourages children to think about why Peter instructed believers to pray, love, welcome others, and serve one another.", "body": ["Question 1 focuses on the purpose of prayer. Prayer is not an attempt to solve every problem through our own strength. It is an expression of faith and dependence on God. Remind your child that they can bring their worries and difficulties to Him.", "Question 2 is especially important this week.", "Peter writes, \"Love covers a multitude of sins.\" This does not mean that we should always hide wrongdoing or pretend that nothing wrong has happened. Rather, love seeks forgiveness and the restoration of relationships instead of continually bringing up someone's faults or using their mistakes against them.", "As children compare teasing a friend for making a mistake with forgiving and continuing to love that friend, help them consider what Peter meant by loving one another deeply.", "It is also important to explain that <b>forgiveness does not mean tolerating bullying, violence, or unsafe behavior.</b> Correcting harmful behavior and asking a trusted adult for help are not contrary to love.", "Question 3 explores why Peter instructed believers to show hospitality without grumbling. Caring for others sometimes requires extra effort and may even feel inconvenient. Peter encourages believers not to become consumed by complaints or resentment but to continue caring for one another with love.", "Serving without grumbling does not mean that we must always feel cheerful. We may still feel tired or overwhelmed. What matters is learning not to treat others as burdens or respond to them with resentment.", "Question 4 helps children consider the purpose of the gifts God has given them. By comparing actions that seek personal attention with actions that help and encourage others, children discover that their gifts are not meant only for themselves.", "<b>The goal of Wednesday is to move beyond seeing Peter's instructions as simple rules and to discover the faith and love that should shape our attitudes and actions.</b>"], "color": "#DCE7C6", "ink": "#44572A"}, "thu": {"day": "Thursday", "name": "God's Heart", "sub": "Getting to Know God's Heart!", "title": "1 Peter 4:10–11", "focus": "Thursday focuses not primarily on what we should do, but on <b>who God is and what the passage reveals about His heart toward us.</b>", "body": ["Question 1 draws attention to the phrase \"God's varied grace.\" God expresses His grace in many different ways. The gifts we receive are connected to His grace, and He does not entrust exactly the same gifts to every person.", "Help your child avoid comparing their abilities with those of others or deciding who is more talented. The important question is not who has the greatest ability, but how each person receives and uses what God has entrusted to them.", "Question 2 helps children discover that God supplies strength to those who serve. God does not simply command us to love and serve others and then leave us to accomplish everything on our own. He provides the strength we need to live according to His Word.", "This can be a meaningful encouragement for children. Sometimes we do not feel patient, kind, or loving enough to care for others. In those moments, we can ask God for His help.", "Question 3 introduces the idea of a \"good steward.\" A steward is someone who has been entrusted with something belonging to another person and is responsible for caring for it faithfully.", "Peter describes believers as stewards of God's grace. God has entrusted His grace to us, not so that we would keep it only for ourselves, but so that we would serve one another.", "This means that God invites us to participate in sharing His grace with others.", "Question 4 focuses on God's glory. Peter teaches that our service should ultimately bring glory to God through Jesus Christ.", "Parents may use the example of a parent feeling joyful when seeing a child show kindness and consideration toward others. However, bringing glory to God involves more than simply doing something that earns His approval.", "It means recognizing that our love and strength come from God and allowing our service to reflect His love and grace.", "<b>On Thursday, help your child discover that God is the One who gives grace, entrusts us with His gifts, and supplies the strength we need to serve others.</b>"], "color": "#FBE3D2", "ink": "#8A4A22"}, "fri": {"day": "Friday", "name": "Into My Life", "sub": "Into My Life!", "title": "1 Peter 4:7–11", "focus": "Friday helps children connect what they have learned throughout the week with their own lives.", "body": ["Question 1 invites children to choose which of Peter's instructions they need most right now: prayer, forgiveness, serving without complaining, or using God's gifts to serve others.", "Whatever your child chooses, encourage them to explain their choice in a comfortable and honest way.", "Question 2 asks children to remember a time when it was difficult to love or help someone. This question is not intended to find fault or make children feel guilty. Its purpose is to help them reflect honestly on their thoughts, feelings, and actions.", "If your child remembers complaining or refusing to help someone, avoid responding with immediate criticism. Instead, listen to what happened and help them understand their own feelings. The goal is to lead children from honest reflection toward asking God for help.", "Question 3 encourages children to choose ways they would like to remember and practice God's love during the coming week. Rather than making them feel responsible for completing every action, encourage them to sincerely practice even one small act of love.", "The final Faith Confession beautifully expresses the central message of this week's devotional:", "\"Thank You, God, for loving me first.\"", "Our faith does not begin with how many good things we accomplish. It begins with God's grace and the love He has already shown us.", "Children then conclude their devotional by asking God to help them love others with His love and serve with the strength He provides.", "<b>On Friday, guide your child to depend not merely on personal determination, but on God's love and strength as they seek to live out His Word.</b>"], "color": "#D6ECF5", "ink": "#2F5A72"}};
var BOOK35={id:'1pe-4-7-11',no:35,ch:4,book:['베드로전서','1 Peter'],title:'기도하고 뜨겁게 사랑해요',ref:'베드로전서 4:7-11',verses:VERSES35,art:'lovingPrayer'};
var MEM35={"id": "1pe-4-7-8", "vi": 0, "ko": ["만물의 마지막이 가까이 왔으니", "그러므로 너희는", "정신을 차리고 근신하여 기도하라", "무엇보다도", "뜨겁게 서로 사랑할지니", "사랑은", "허다한 죄를 덮느니라"], "en": ["The end of all things is at hand;", "therefore be self-controlled", "and sober-minded for the sake of your prayers.", "Above all, keep loving one another earnestly,", "since love covers a multitude of sins."]};
