/* ---------- #36 · 베드로후서 3:8-13 · 다시 오실 예수님을 기다리며 거룩하게 살아요 (2026.11.23–11.29) ---------- */
var VERSES36=[[8, "사랑하는 자들아 주께는 하루가 천 년 같고 천 년이 하루 같다는 이 한 가지를 잊지 말라", "But do not overlook this one fact, beloved, that with the Lord one day is as a thousand years, and a thousand years as one day."], [9, "주의 약속은 어떤 이들이 더디다고 생각하는 것 같이 더딘 것이 아니라 오직 주께서는 너희를 대하여 오래 참으사 아무도 멸망하지 아니하고 다 회개하기에 이르기를 원하시느니라", "The Lord is not slow to fulfill his promise as some count slowness, but is patient toward you, not wishing that any should perish, but that all should reach repentance.", 1], [10, "그러나 주의 날이 도둑 같이 오리니 그 날에는 하늘이 큰 소리로 떠나가고 물질이 뜨거운 불에 풀어지고 땅과 그 중에 있는 모든 일이 드러나리로다", "But the day of the Lord will come like a thief, and then the heavens will pass away with a roar, and the heavenly bodies will be burned up and dissolved, and the earth and the works that are done on it will be exposed."], [11, "이 모든 것이 이렇게 풀어지리니 너희가 어떠한 사람이 되어야 마땅하냐 거룩한 행실과 경건함으로", "Since all these things are thus to be dissolved, what sort of people ought you to be in lives of holiness and godliness,"], [12, "하나님의 날이 임하기를 바라보고 간절히 사모하라 그 날에 하늘이 불에 타서 풀어지고 물질이 뜨거운 불에 녹아지려니와", "waiting for and hastening the coming of the day of God, because of which the heavens will be set on fire and dissolved, and the heavenly bodies will melt as they burn!"], [13, "우리는 그의 약속대로 의가 있는 곳인 새 하늘과 새 땅을 바라보도다", "But according to his promise we are waiting for new heavens and a new earth in which righteousness dwells."]];
var BIBLE36={"2pe": {"3": {"8": ["사랑하는 자들아 주께는 하루가 천 년 같고 천 년이 하루 같다는 이 한 가지를 잊지 말라", "But do not overlook this one fact, beloved, that with the Lord one day is as a thousand years, and a thousand years as one day."], "9": ["주의 약속은 어떤 이들이 더디다고 생각하는 것 같이 더딘 것이 아니라 오직 주께서는 너희를 대하여 오래 참으사 아무도 멸망하지 아니하고 다 회개하기에 이르기를 원하시느니라", "The Lord is not slow to fulfill his promise as some count slowness, but is patient toward you, not wishing that any should perish, but that all should reach repentance."], "10": ["그러나 주의 날이 도둑 같이 오리니 그 날에는 하늘이 큰 소리로 떠나가고 물질이 뜨거운 불에 풀어지고 땅과 그 중에 있는 모든 일이 드러나리로다", "But the day of the Lord will come like a thief, and then the heavens will pass away with a roar, and the heavenly bodies will be burned up and dissolved, and the earth and the works that are done on it will be exposed."], "11": ["이 모든 것이 이렇게 풀어지리니 너희가 어떠한 사람이 되어야 마땅하냐 거룩한 행실과 경건함으로", "Since all these things are thus to be dissolved, what sort of people ought you to be in lives of holiness and godliness,"], "12": ["하나님의 날이 임하기를 바라보고 간절히 사모하라 그 날에 하늘이 불에 타서 풀어지고 물질이 뜨거운 불에 녹아지려니와", "waiting for and hastening the coming of the day of God, because of which the heavens will be set on fire and dissolved, and the heavenly bodies will melt as they burn!"], "13": ["우리는 그의 약속대로 의가 있는 곳인 새 하늘과 새 땅을 바라보도다", "But according to his promise we are waiting for new heavens and a new earth in which righteousness dwells."]}}};
var LESSONS36={"mon": {"name": "마음 열기", "tag": "OPEN OUR HEARTS", "title": "말씀 속으로 들어가요!", "en": "Feel the Story!", "color": "#F6D6D1", "ink": "#7A3A35", "teaser": "기다리는 시간은 어떻게 느껴질까요?", "qs": [{"type": "pick", "label": "하나 고르기", "q": "기다리는 동안 시간이 어떻게 느껴졌나요?", "en": "How did time feel while you were waiting?", "opts": [["빨리 지나갔어요.", "Fast"], ["천천히 지나갔어요.", "Slow"], ["잘 모르겠어요.", "Not sure"]], "ok": "좋아요! 기다리는 시간을 느껴 봤어요."}, {"type": "multi", "free": true, "label": "모두 고르기", "q": "기다리는 동안 어떤 마음이 들었나요? 모두 골라 보세요.", "en": "How did you feel while waiting? Check all that apply.", "opts": [["기대되었어요.", "Excited"], ["지루했어요.", "Bored"], ["빨리 받고 싶었어요.", "Impatient"], ["정말 받을 수 있을지 궁금했어요.", "Unsure"]], "answer": [0, 1, 2, 3], "ok": "좋아요! 어떤 마음이든 괜찮아요."}, {"type": "text", "label": "써 보기 · 8절", "q": "8절에서는 하나님께 하루가 천 년 같고 천 년이 하루 같다고 말씀해요. 이 말씀을 읽으면 무엇이 궁금한가요?", "en": "Verse 8 says, “with the Lord one day is as a thousand years, and a thousand years as one day.” What does this make you wonder?", "ph": "내가 궁금한 것", "ok": "좋은 질문이에요!"}, {"type": "text", "label": "써 보기", "q": "예수님이 다시 오시기를 오랫동안 기다리던 사람들은 어떤 마음이었을까요?", "en": "Imagine people waiting a long time for Jesus to return. How might they have felt?", "ph": "기다리던 사람들의 마음", "ok": "잘했어요! 기다리던 사람들의 마음을 상상해 봤어요."}], "activity": {"title": "선택활동", "en": "Optional Activity", "ko": "좋아하는 간식을 먹기 전, 3분 동안 기다려 보세요. 활동을 하지 않는다면 무언가를 기다렸던 경험을 떠올려 보세요.", "enText": "Wait 3 minutes before eating your favorite snack. Or think about a time you waited for something."}}, "tue": {"name": "말씀 찾기", "tag": "VIEWING WHAT HAS BEEN GIVEN", "title": "말씀에 있는 그대로 찾아요", "en": "Explore the Word.", "color": "#E1DBF8", "ink": "#4F4290", "teaser": "하나님은 더디신 걸까요, 오래 참으시는 걸까요?", "qs": [{"type": "blanks", "label": "빈칸 채우기 · 9절", "q": "9절을 읽고 주어진 단어로 빈칸을 채워 보세요.", "en": "Read verse 9. Fill in the blanks using the words below.", "lines": [["주님은 약속을 지키시는 데 ", 0, " 것이 아니라, 우리를 ", 1, " 분이에요."]], "words": ["더디신", "오래 참으시는"], "answers": ["더디신", "오래 참으시는"], "ok": "맞아요! 하나님은 더디신 것이 아니라 오래 참으시는 분이에요."}, {"type": "single", "label": "고르기 · 9절", "q": "하나님은 모든 사람이 어떻게 하기를 원하시나요?", "en": "What does God want everyone to do?", "opts": [["부자가 되는 것", "Become rich"], ["회개하는 것", "Repent"], ["유명해지는 것", "Become famous"]], "answer": 1, "ok": "맞아요! 하나님은 모든 사람이 회개하기를 원하세요.", "no": "9절을 다시 읽어 볼까요?"}, {"type": "match", "label": "짝 맞추기 · 10–12절", "q": "각 말씀에서 알려주는 내용을 연결해 보세요. 왼쪽을 누르고 알맞은 것을 오른쪽에서 눌러요.", "en": "Match each verse with what it tells us. Tap the left, then tap the matching answer on the right.", "left": [["10절", "Verse 10"], ["11절", "Verse 11"], ["12절", "Verse 12"]], "right": [["거룩하고 경건하게 살아가요.", "Live holy and godly lives."], ["하나님의 날을 간절히 기다려요.", "Look forward to the day of God."], ["주의 날이 도둑같이 찾아와요.", "The day of the Lord will come like a thief."]], "answer": [2, 0, 1], "ok": "모두 맞았어요! 10절, 11절, 12절의 내용을 잘 찾았어요."}, {"type": "blanks", "label": "빈칸 채우기 · 13절", "q": "우리는 하나님의 약속을 따라 무엇을 기다리고 있나요?", "en": "What are we waiting for according to God's promise?", "lines": [["우리는 하나님의 약속대로 ", 0, "가 있는 곳인 ", 1, "과 ", 2, "을 바라보아요."]], "words": ["새 하늘", "새 땅", "의"], "answers": ["의", "새 하늘", "새 땅"], "ok": "맞아요! 의가 있는 새 하늘과 새 땅을 기다려요."}]}, "wed": {"name": "숨은 이야기", "tag": "FINDING HIDDEN STORIES", "title": "왜 그렇게 행동했을까요?", "en": "Why Did They Act That Way?", "color": "#DCE7C6", "ink": "#44572A", "teaser": "재림과 거룩한 삶은 어떤 관계일까요?", "qs": [{"type": "single", "label": "고르기 · 10절", "q": "베드로는 왜 주의 날이 ‘도둑같이’ 올 것이라고 말했을까요?", "en": "Why does Peter say the day of the Lord will come “like a thief”?", "opts": [["밤에만 일어나기 때문에", "Because it will only happen at night."], ["언제 그날이 올지 모르기 때문에", "Because we don't know when it will come."], ["예수님이 우리의 물건을 가져가시기 때문에", "Because Jesus will take our things."]], "answer": 1, "ok": "맞아요! 언제 그날이 올지 모르기 때문이에요.", "no": "10절을 다시 읽어 볼까요?"}, {"type": "text", "label": "써 보기 · 11절", "q": "어떤 사람이 “예수님이 아직 다시 오시지 않았으니까 내 마음대로 살아도 괜찮아!”라고 말한다면, 베드로는 그 사람에게 무엇이라고 말했을까요?", "en": "Imagine someone says, “Jesus hasn't returned yet, so I can live however I want!” What would Peter say to this person?", "ph": "베드로가 해 줄 말", "ok": "잘했어요! 거룩한 행실과 경건함으로 살라고 했을 거예요.", "helpbox": {"title": "도움말", "items": [["거룩한 행실", "하나님이 기뻐하시는 행동을 선택하는 것"], ["경건함", "매일 하나님을 사랑하고 공경하며 살아가는 것"]]}}, {"type": "single", "label": "고르기 · 13절", "q": "베드로는 왜 새 하늘과 새 땅에 대한 하나님의 약속을 다시 생각하게 했을까요?", "en": "Why does Peter remind us of God's promise of new heavens and a new earth?", "opts": [["소망을 가지고 기다리도록", "To help us wait with hope."], ["미래를 두려워하게 하려고", "To make us afraid of the future."], ["예수님이 다시 오실 날짜를 알려주려고", "To tell us exactly when Jesus will return."]], "answer": 0, "ok": "맞아요! 소망을 가지고 기다리도록 하려고 했어요.", "no": "13절을 다시 읽어 볼까요?"}]}, "thu": {"name": "하나님 마음", "tag": "ENCOUNTERING THE HEART OF GOD", "title": "하나님의 마음을 알아가요!", "en": "Getting to Know God's Heart!", "color": "#FBE3D2", "ink": "#8A4A22", "teaser": "하나님의 사랑과 의로우심", "qs": [{"type": "single", "label": "고르기 · 9절", "q": "하나님은 사람들이 회개하기를 오래 참고 기다리세요(9절). 이것은 하나님의 어떤 마음을 보여주나요?", "en": "God patiently waits for people to repent (v. 9). What does this tell us about God's heart?", "opts": [["하나님은 약속을 잊어버리셨어요.", "God has forgotten His promise."], ["하나님은 사람들이 하나님께 돌아오기를 원하세요.", "God wants people to turn back to Him."], ["하나님은 죄를 중요하지 않게 생각하세요.", "God thinks sin is not important."], ["하나님은 사람들에게 관심이 없으세요.", "God does not care about people."]], "answer": 1, "ok": "맞아요! 하나님은 사람들이 돌아오기를 원하세요.", "no": "9절을 다시 읽어 볼까요?"}, {"type": "blanks", "label": "고르기 · 13절", "q": "하나님은 의가 있는 새 하늘과 새 땅을 약속하셨어요(13절). 알맞은 단어를 골라 빈칸에 넣어요.", "en": "God promises new heavens and a new earth where righteousness dwells (v. 13). Choose the correct words.", "lines": [["하나님은 ", 0, " 가득한 세상을 원하세요."], ["하나님은 ", 1, " 분이에요."]], "words": ["의", "악", "의로우신", "불공평하신"], "answers": ["의", "의로우신"], "ok": "맞아요! 하나님은 의로우신 분이에요."}, {"type": "match", "label": "짝 맞추기", "q": "하나님께서 하시는 일을 통해 하나님의 어떤 마음을 알 수 있을까요? 왼쪽을 누르고 알맞은 것을 오른쪽에서 눌러요.", "en": "What do God's actions reveal about His heart? Tap the left, then tap the matching answer on the right.", "left": [["하나님은 사람들이 회개하기를 오래 참고 기다리세요. (9절)", "God patiently waits for people to repent. (v. 9)"], ["하나님은 의가 있는 새 하늘과 새 땅을 약속하세요. (13절)", "God promises new heavens and a new earth where righteousness dwells. (v. 13)"]], "right": [["하나님은 의로우시며 악을 영원히 그대로 두지 않으세요.", "God is righteous and will not allow evil to last forever."], ["하나님은 사람들을 사랑하시고 하나님께 돌아오기를 원하세요.", "God loves people and wants them to turn back to Him."]], "answer": [1, 0], "ok": "모두 맞았어요! 하나님은 사랑이 많으시고 의로우세요."}]}, "fri": {"name": "내 삶으로", "tag": "INTO MY LIFE", "title": "나는 어떻게 살아야 할까요?", "en": "How Should I Live?", "color": "#FBEBB8", "ink": "#6E5410", "teaser": "소망을 가지고 기다리며 살아요", "qs": [{"type": "multi", "free": true, "label": "모두 고르기 · 13절", "q": "예수님의 재림과 하나님의 약속을 생각하면 어떤 마음이 드나요? 해당하는 것을 모두 골라요.", "en": "How do you feel about Jesus' return and God's promise? Choose all that apply.", "opts": [["다시 오실 예수님을 기대하며 기다려요.", "I look forward to Jesus coming again."], ["예수님이 다시 오실 날은 어떤 날일지 궁금해요.", "I wonder what that day will be like."], ["그날 어떤 일이 일어날지 몰라 조금 걱정돼요.", "I feel a little worried because I don't know what will happen."]], "answer": [0, 1, 2], "ok": "좋아요! 어떤 마음이든 하나님께 말씀드릴 수 있어요."}, {"type": "multi", "free": true, "label": "모두 고르기", "q": "예수님이 다시 오시기를 기다리며 우리는 어떻게 살아갈 수 있을까요? 실천하고 싶은 것을 모두 골라요.", "en": "How can we live while waiting for Jesus to return? Check all the things you want to practice.", "opts": [["잘못된 행동을 돌이키고 하나님께 용서를 구해요.", "Turn away from wrong choices and ask God for forgiveness."], ["어려울 때에도 다른 사람을 사랑하고 도와요.", "Love and help others, even when it's hard."], ["하나님이 기뻐하시는 행동을 선택해요.", "Choose to do what pleases God."], ["기도하며 하나님의 약속을 믿어요.", "Pray and trust God's promises."]], "answer": [0, 1, 2, 3], "ok": "멋져요! 소망을 가지고 기다리며 살아가요."}, {"type": "fill", "label": "써 보기", "q": "2번에서 한 가지를 골라 보세요. 이번 주에 어떻게 실천할 수 있을까요?", "en": "Choose one thing from Question 2. How will you practice it this week?", "parts": ["이번 주에 나는 ", 0], "ok": "좋아요! 한 가지라도 진심으로 실천해 봐요."}], "confess": {"title": "기억해요!", "en": "Remember!", "ko": ["하나님은 약속을 반드시 지키세요.", "예수님은 다시 오실 거예요!", "나는 소망을 가지고 기다리며 하나님이 기뻐하시는 삶을 살겠어요."], "enLines": ["God keeps His promises.", "Jesus will come again!", "I will wait with hope and live in ways that please God."]}}};
var LESSONS36_EN={"mon": {"name": "Open Hearts", "title": "Feel the Story!", "teaser": "How does waiting feel?", "qs": [{"label": "Choose one", "ok": "Good! You felt the time of waiting.", "q": "How did time feel while you were waiting?"}, {"label": "Choose all", "ok": "Good! Any feeling is okay.", "q": "How did you feel while waiting? Check all that apply."}, {"label": "Write · v. 8", "ok": "Good question!", "ph": "What I wonder", "q": "Verse 8 says, “with the Lord one day is as a thousand years, and a thousand years as one day.” What does this make you wonder?"}, {"label": "Write", "ok": "Well done! You imagined how the waiting people felt.", "ph": "How the waiting people felt", "q": "Imagine people waiting a long time for Jesus to return. How might they have felt?"}]}, "tue": {"name": "Find the Word", "title": "Explore the Word.", "teaser": "Is God slow, or patient?", "qs": [{"label": "Fill in the blanks · v. 9", "ok": "That’s right! God is not slow, He is patient.", "lines": [["The Lord is not ", 0, " to fulfill His promise, but is ", 1, " toward you."]], "wordsEn": ["slow", "patient"], "q": "Read verse 9. Fill in the blanks using the words below."}, {"label": "Choose · v. 9", "ok": "That’s right! God wants everyone to repent.", "no": "Let’s read verse 9 again.", "q": "What does God want everyone to do?"}, {"label": "Match · vv. 10–12", "ok": "All correct! You found what verses 10, 11 and 12 say.", "q": "Match each verse with what it tells us. Tap the left, then tap the matching answer on the right."}, {"label": "Fill in the blanks · v. 13", "ok": "That’s right! We wait for new heavens and a new earth where righteousness dwells.", "lines": [["According to God's promise, we are waiting for ", 1, " and a ", 2, " in which ", 0, " dwells."]], "wordsEn": ["new heavens", "new earth", "righteousness"], "q": "What are we waiting for according to God's promise?"}]}, "wed": {"name": "Hidden Story", "title": "Why Did They Act That Way?", "teaser": "How are Jesus' return and holy living connected?", "qs": [{"label": "Choose · v. 10", "ok": "That’s right! We don’t know when it will come.", "no": "Let’s read verse 10 again.", "q": "Why does Peter say the day of the Lord will come “like a thief”?"}, {"label": "Write · v. 11", "ok": "Well done! Peter would say to live in holiness and godliness.", "ph": "What Peter would say", "q": "Imagine someone says, “Jesus hasn't returned yet, so I can live however I want!” What would Peter say to this person?", "helpbox": {"title": "Hint", "items": [["Holiness", "Choosing what pleases God."], ["Godliness", "Loving and honoring God each day."]]}}, {"label": "Choose · v. 13", "ok": "That’s right! To help us wait with hope.", "no": "Let’s read verse 13 again.", "q": "Why does Peter remind us of God's promise of new heavens and a new earth?"}]}, "thu": {"name": "God's Heart", "title": "Getting to Know God's Heart!", "teaser": "God's love and righteousness", "qs": [{"label": "Choose · v. 9", "ok": "That’s right! God wants people to turn back to Him.", "no": "Let’s read verse 9 again.", "q": "God patiently waits for people to repent (v. 9). What does this tell us about God's heart?"}, {"label": "Choose words · v. 13", "ok": "That’s right! God is righteous.", "lines": [["God wants a world filled with ", 0, "."], ["God is ", 1, "."]], "wordsEn": ["righteousness", "wickedness", "righteous", "unfair"], "q": "God promises new heavens and a new earth where righteousness dwells (v. 13). Choose the correct words."}, {"label": "Match", "ok": "All correct! God is loving and righteous.", "q": "What do God's actions reveal about His heart? Tap the left, then tap the matching answer on the right."}]}, "fri": {"name": "Into My Life", "title": "How Should I Live?", "teaser": "Waiting with hope", "qs": [{"label": "Choose all · v. 13", "ok": "Good! You can tell God how you feel, whatever it is.", "q": "How do you feel about Jesus' return and God's promise? Choose all that apply."}, {"label": "Choose all", "ok": "Wonderful! Let’s live while waiting with hope.", "q": "How can we live while waiting for Jesus to return? Check all the things you want to practice."}, {"label": "Write", "ok": "Good! Even one small act, done sincerely, matters.", "parts": ["This week, I will ", 0], "q": "Choose one thing from Question 2. How will you practice it this week?"}]}};
