var MEM36={"id": "2pe-3-9", "vi": 1, "ko": ["주의 약속은", "어떤 이들이 더디다고 생각하는 것 같이", "더딘 것이 아니라", "오직 주께서는", "너희를 대하여 오래 참으사", "아무도 멸망하지 아니하고", "다 회개하기에 이르기를 원하시느니라"], "en": ["The Lord is not slow to fulfill his promise", "as some count slowness,", "but is patient toward you,", "not wishing that any should perish,", "but that all should reach repentance."]};
